insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('967ee554-1fc1-4a8d-a6ee-e5c86939f520', 'N5', 'V1て、V2て、～Vます', 'Liệt kê nhiều hành động theo trình tự', 'Mỗi động từ trước chuyển sang thể て, chỉ động từ cuối chia đúng thì', 'V1(thể て) + V2(thể て) + ... + V cuối(thể ます/ました)', 'Kể lại nhiều hành động xảy ra liên tiếp theo trình tự thời gian', NULL, NULL, NULL, '{"Aい→くて、～／Aな→で、～"}', NULL, 42, 'V1て、V2て、～Vます', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('ef709bc5-f430-420d-887d-94e16a27ec82', 'N5', 'Aい→くて、～／Aな→で、～', 'Liệt kê nhiều tính từ', 'Aい bỏ い thêm くて; Aな thêm で trực tiếp', 'Aい → Aくて、～ ； Aな → Aで、～', 'Liệt kê nhiều đặc điểm/tính chất của cùng 1 chủ thể', NULL, NULL, NULL, '{"V1て、V2て、～Vます"}', NULL, 42, 'Aい→くて、～／Aな→で、～', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('87c80aaf-685d-4c41-a251-8ac6f92ff010', 'N5', 'V1てから、V2ます', 'Sau khi làm V1, làm V2', 'てから nhấn mạnh trình tự trước-sau rõ ràng hơn V1て、V2て', 'V1(thể て) + から、+ V2(thể ます)', 'Nhấn mạnh V2 chỉ xảy ra sau khi V1 đã hoàn thành', NULL, NULL, NULL, '{}', NULL, 42, 'V1てから、V2ます', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('b7a61e42-ea45-482b-b008-eb0a37746785', 'N5', 'N1 は N2 が Tính từ です', 'Miêu tả đặc điểm, tính chất của sự vật/con người thông qua 1 bộ phận/khía cạnh cụ thể', 'N1 là chủ thể chung, N2 là bộ phận/khía cạnh cụ thể được miêu tả', 'N1(chủ thể) + は + N2(bộ phận/khía cạnh) + が + Tính từ + です', 'Miêu tả 1 đặc điểm cụ thể (ví dụ mái tóc, đồ ăn) thuộc về chủ thể chung N1', NULL, NULL, NULL, '{}', NULL, 42, 'N1 は N2 が Tính từ です', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('5141ffd8-14ba-40df-a1ef-d747a4b29fc2', 'N5', 'どうやって ～ Vますか', 'Làm như thế nào (hỏi cách thức chung, không chỉ riêng phương tiện di chuyển)', 'どうやって hỏi cách thức thực hiện 1 việc bất kỳ, phạm vi rộng hơn なにで', 'どうやって + V ますか', 'Hỏi cách thức/phương pháp thực hiện 1 hành động', NULL, NULL, NULL, '{"なにで／どうやって [V di chuyển] か"}', NULL, 42, 'どうやって ～ Vますか', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('f0086732-514c-4797-8f1e-0ae4fe7e1d2f', 'N5', 'どの N', 'N nào? (chọn 1 trong nhiều N đã biết, có mô tả kèm theo)', 'どのN hỏi + trả lời thường có mệnh đề mô tả bổ nghĩa cho N', 'N1 は どの N2 ですか。→ (mô tả) + N2 です。', 'Hỏi và xác định 1 đối tượng cụ thể trong nhóm nhiều đối tượng cùng loại', NULL, NULL, NULL, '{"どう、どんな、どれ"}', NULL, 42, 'どの N', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('f40a7deb-c72b-4ac0-86e3-e9dff85b7122', 'N5', '動詞ない形（thể phủ định của động từ）', 'Thể ない (thể phủ định thông thường) của động từ, tương đương ～ません', 'Nhóm I: hàng う→hàng あ+ない; Nhóm II: bỏ ます thêm ない; Nhóm III: する→しない, くる→こない', 'Nhóm I: chuyển âm cuối hàng う → hàng あ + ない ； Nhóm II: bỏ ます thêm ない ； Nhóm III: する→しない, くる→こない, Nする→Nしない', 'Dạng phủ định thông thường của động từ, làm nền cho nhiều mẫu như ないでください/なければなりません/なくてもいいです', 'thông thường (không lịch sự)', NULL, NULL, '{}', NULL, 42, '動詞ない形（thể phủ định của động từ）', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('65747019-393a-49b4-8e04-6621e8d0988e', 'N5', 'V ないでください', 'Xin đừng.../Hãy đừng làm gì', 'ないでください = yêu cầu lịch sự đừng làm gì, ngược nghĩa với てください', 'V(thể ない) + で + ください', 'Yêu cầu/nhờ ai đó đừng làm 1 việc, một cách lịch sự', 'lịch sự', NULL, NULL, '{"V てください","V てはいけません"}', NULL, 42, 'V ないでください', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('cdf7ec05-00a9-496e-9396-29a35d7981c8', 'N5', 'V なければなりません（V ないといけない）', 'Phải làm...(bắt buộc)', 'なければなりません = phải làm, mất đi không được — chuyển từ thể ない bỏ い thêm ければなりません', 'V(thể ない, bỏ い) + ければなりません', 'Diễn tả nghĩa vụ/sự bắt buộc phải thực hiện 1 hành động', NULL, 'Đồng nghĩa: V(thể ない) + と + いけない.', NULL, '{"V ないでください"}', NULL, 42, 'V なければなりません（V ないといけない）', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('18c29cf8-6f61-431d-9938-736ad58b1094', 'N5', 'V なくてもいいです', 'Không phải làm...cũng được／Không cần...(đâu)', 'なくてもいいです ngược nghĩa với なければなりません', 'V(thể ない, bỏ い) + くてもいいです', 'Diễn tả việc không bắt buộc phải làm, làm hay không cũng được', NULL, NULL, NULL, '{"V なければなりません（V ないといけない）"}', NULL, 42, 'V なくてもいいです', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('90ce4214-9813-49b4-9a40-d9d1eaf74a82', 'N5', 'A は～（nhấn mạnh A）', 'A thì ~ (nhấn mạnh, tương phản riêng A với các đối tượng khác)', 'Đặt は sau 1 danh từ giữa câu để nhấn mạnh/tương phản riêng nó', '(mệnh đề) + N + は + (phần còn lại của câu)', 'Nhấn mạnh 1 đối tượng cụ thể, ngụ ý các đối tượng khác thì không như vậy (tương phản ngầm)', NULL, 'So với câu gốc không nhấn mạnh, việc thêm は vào giữa câu tạo sắc thái "riêng cái này thì...", ngụ ý cái khác thì không sao.', NULL, '{}', NULL, 42, 'A は～（nhấn mạnh A）', 'pdf', 'ok')
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('967ee554-1fc1-4a8d-a6ee-e5c86939f520', NULL, 1, 'standard', '今朝ジョギングをして、シャワーを浴びて、学校へ行きました。', 'Sáng nay tôi đã đi bộ thể dục, tắm rửa, đi học.', '今朝ジョギングを＿＿＿、シャワーを浴びて、学校へ行きました。', 'して', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('967ee554-1fc1-4a8d-a6ee-e5c86939f520', NULL, 2, 'standard', '昨日の晩、友達と食事して、映画を見て、それから家に帰りました。', 'Tối hôm qua, tôi đã cùng bạn ăn tối, xem phim, sau đó về nhà.', '昨日の晩、友達と食事して、映画を＿＿＿、それから家に帰りました。', '見て', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('967ee554-1fc1-4a8d-a6ee-e5c86939f520', NULL, 3, 'daily', '顔を洗って、朝ご飯を食べて、学校へ行きます。', 'Tôi rửa mặt, ăn sáng, rồi đi học.', '顔を＿＿＿、朝ご飯を食べて、学校へ行きます。', '洗って', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ef709bc5-f430-420d-887d-94e16a27ec82', NULL, 1, 'standard', '私の部屋は広くて、きれいです。', 'Căn phòng của tôi rộng và sạch sẽ.', '私の部屋は＿＿＿、きれいです。', '広くて', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ef709bc5-f430-420d-887d-94e16a27ec82', NULL, 2, 'standard', 'Linhさんのうちは大きくて、新しいです。', 'Nhà của chị Linh to và mới.', 'Linhさんのうちは＿＿＿、新しいです。', '大きくて', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ef709bc5-f430-420d-887d-94e16a27ec82', NULL, 3, 'daily', 'この店は静かで、安いです。', 'Quán này yên tĩnh và rẻ.', 'この店は＿＿＿、安いです。', '静かで', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('87c80aaf-685d-4c41-a251-8ac6f92ff010', NULL, 1, 'standard', '今朝ご飯を食べてから、学校に行きました。', 'Sáng nay sau khi ăn sáng thì tôi đi trường.', '今朝ご飯を食べ＿＿＿、学校に行きました。', 'てから', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('87c80aaf-685d-4c41-a251-8ac6f92ff010', NULL, 2, 'daily', '宿題をしてから、テレビを見ます。', 'Sau khi làm bài tập, tôi xem tivi.', '宿題をし＿＿＿、テレビを見ます。', 'てから', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('87c80aaf-685d-4c41-a251-8ac6f92ff010', NULL, 3, 'daily', 'シャワーを浴びてから、寝ます。', 'Sau khi tắm, tôi đi ngủ.', 'シャワーを浴び＿＿＿、寝ます。', 'てから', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('b7a61e42-ea45-482b-b008-eb0a37746785', NULL, 1, 'standard', 'Huongさんは髪が長いです。', 'Chị Hương có mái tóc dài.', 'Huongさんは髪＿＿＿長いです。', 'が', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('b7a61e42-ea45-482b-b008-eb0a37746785', NULL, 2, 'standard', 'ハノイは食べ物が美味しくて、安いです。', 'Hà Nội có đồ ăn ngon và rẻ.', 'ハノイは食べ物＿＿＿美味しくて、安いです。', 'が', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('b7a61e42-ea45-482b-b008-eb0a37746785', NULL, 3, 'daily', 'この犬は目が大きいです。', 'Con chó này có đôi mắt to.', 'この犬は目＿＿＿大きいです。', 'が', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('5141ffd8-14ba-40df-a1ef-d747a4b29fc2', NULL, 1, 'standard', 'どうやって学校へ行きましたか。', 'Bạn đã đi đến trường như thế nào?', '＿＿＿学校へ行きましたか。', 'どうやって', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('5141ffd8-14ba-40df-a1ef-d747a4b29fc2', NULL, 2, 'standard', 'バスで行きました。', 'Tôi đã đi bằng xe bus.', 'バス＿＿＿行きました。', 'で', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('5141ffd8-14ba-40df-a1ef-d747a4b29fc2', NULL, 3, 'daily', 'どうやってこのケーキを作りましたか。', 'Bạn đã làm bánh này như thế nào?', '＿＿＿このケーキを作りましたか。', 'どうやって', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f0086732-514c-4797-8f1e-0ae4fe7e1d2f', NULL, 1, 'standard', 'Hoaさんはどの人ですか。', 'Chị Hoa là người nào?', 'Hoaさんは＿＿＿人ですか。', 'どの', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f0086732-514c-4797-8f1e-0ae4fe7e1d2f', NULL, 2, 'standard', '髪が長くて、背が高い人です。', 'Là người tóc dài và dáng cao.', '髪が長くて、背が＿＿＿人です。', '高い', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f0086732-514c-4797-8f1e-0ae4fe7e1d2f', NULL, 3, 'daily', '田中さんはどの人ですか。', 'Anh Tanaka là người nào?', '田中さんは＿＿＿人ですか。', 'どの', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f40a7deb-c72b-4ac0-86e3-e9dff85b7122', NULL, 1, 'standard', '行きません。', 'Không đi.', '＿＿＿。', '行きません', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f40a7deb-c72b-4ac0-86e3-e9dff85b7122', NULL, 2, 'standard', '行かない。', 'Không đi (thân mật).', '＿＿＿。', '行かない', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f40a7deb-c72b-4ac0-86e3-e9dff85b7122', NULL, 3, 'daily', '食べない。', 'Không ăn (thân mật).', '＿＿＿。', '食べない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('65747019-393a-49b4-8e04-6621e8d0988e', NULL, 1, 'standard', '今元気ですから、心配しないでください。', 'Bây giờ tôi khỏe mạnh nên xin đừng lo lắng.', '今元気ですから、心配＿＿＿。', 'しないでください', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('65747019-393a-49b4-8e04-6621e8d0988e', NULL, 2, 'standard', 'ここに車を止めないでください。', 'Đừng đỗ ô tô ở đây.', 'ここに車を＿＿＿。', '止めないでください', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('65747019-393a-49b4-8e04-6621e8d0988e', NULL, 3, 'daily', '写真を撮らないでください。', 'Xin đừng chụp ảnh.', '写真を＿＿＿。', '撮らないでください', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('cdf7ec05-00a9-496e-9396-29a35d7981c8', NULL, 1, 'standard', '病気ですから、薬を飲まなければなりません。', 'Vì bị ốm nên phải uống thuốc.', '病気ですから、薬を＿＿＿。', '飲まなければなりません', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('cdf7ec05-00a9-496e-9396-29a35d7981c8', NULL, 2, 'daily', '明日、早く起きなければなりません。', 'Ngày mai tôi phải dậy sớm.', '明日、早く＿＿＿。', '起きなければなりません', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('cdf7ec05-00a9-496e-9396-29a35d7981c8', NULL, 3, 'daily', 'レポートを書かないといけない。', 'Tôi phải viết báo cáo.', 'レポートを＿＿＿。', '書かないといけない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('18c29cf8-6f61-431d-9938-736ad58b1094', NULL, 1, 'standard', '明日来なくてもいいです。', 'Ngày mai không cần đến đâu.', '明日＿＿＿。', '来なくてもいいです', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('18c29cf8-6f61-431d-9938-736ad58b1094', NULL, 2, 'daily', '今日は勉強しなくてもいいです。', 'Hôm nay không cần học bài cũng được.', '今日は＿＿＿。', '勉強しなくてもいいです', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('18c29cf8-6f61-431d-9938-736ad58b1094', NULL, 3, 'daily', '傘を持たなくてもいいです。', 'Không cần mang ô cũng được.', '傘を＿＿＿。', '持たなくてもいいです', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('90ce4214-9813-49b4-9a40-d9d1eaf74a82', NULL, 1, 'standard', 'ここに車を止めないでください。', 'Đừng đỗ ô tô ở đây.', 'ここに車を＿＿＿。', '止めないでください', 'pdf');
