insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('967ee554-1fc1-4a8d-a6ee-e5c86939f520', NULL, 'choose_connection', 'Cách nối đúng của mẫu "V1て、V2て、～Vます" (Liệt kê nhiều hành động theo trình tự) là gì?', 'V1(thể て) + から、+ V2(thể ます)', 'V1(thể て) + V2(thể て) + ... + V cuối(thể ます/ました)', 'V(thể ない, bỏ い) + ければなりません', 'N1 は どの N2 ですか。→ (mô tả) + N2 です。', 'V1(thể て) + V2(thể て) + ... + V cuối(thể ます/ました)', 'generated');
