insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('90ce4214-9813-49b4-9a40-d9d1eaf74a82', NULL, 'choose_connection', 'Cách nối đúng của mẫu "A は～（nhấn mạnh A）" (A thì ~ (nhấn mạnh, tương phản riêng A với các đối tượng khác)) là gì?', 'V1(thể て) + V2(thể て) + ... + V cuối(thể ます/ました)', 'Nhóm I: chuyển âm cuối hàng う → hàng あ + ない ； Nhóm II: bỏ ます thêm ない ； Nhóm III: する→しない, くる→こない, Nする→Nしない', 'N1(chủ thể) + は + N2(bộ phận/khía cạnh) + が + Tính từ + です', '(mệnh đề) + N + は + (phần còn lại của câu)', '(mệnh đề) + N + は + (phần còn lại của câu)', 'generated');
